def poly(z, d):
    from itertools import combinations_with_replacement
    return np.column_stack([np.prod(z[:, i], axis=1) for k in range(d + 1) for i in combinations_with_replacement(range(z.shape[1]), k)])

def basis(x, d):
    from itertools import combinations_with_replacement
    terms = [i for k in range(d + 1) for i in combinations_with_replacement(range(4), k)]
    return (np.column_stack([np.prod(x[:, i], axis=1) for i in terms]), terms)
